INSERT INTO articles (source_id, original_url, title, published_at, ai_summary) VALUES ((SELECT id FROM sources LIMIT 1), 'https://fake-poll-news.com/esonero', 'Tifosi infuriati: esonero in vista?', NOW(), '{ "category": "Polemica", "sentiment": "Negativo", "excerpt": "Clima teso a Trigoria dopo la sconfitta. Tifosi divisi sul futuro dell''allenatore.", "content": "La situazione a Trigoria è diventata insostenibile dopo le recenti prestazioni. La dirigenza starebbe valutando un cambio clamoroso in panchina. Sui social i tifosi sono letteralmente spaccati a metà tra chi invoca il ritorno di un sergente di ferro e chi preferirebbe non distruggere il progetto tecnico a stagione in corso. Nelle prossime 48 ore sono attese comunicazioni ufficiali.", "poll": { "question": "Chi vorreste come nuovo allenatore della Roma?", "options": ["Massimiliano Allegri", "Maurizio Sarri", "Tenere l''attuale fino a fine anno"] } }'::jsonb);